ALTER TABLE public.organizations ADD COLUMN IF NOT EXISTS operational_profile jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE IF NOT EXISTS public.organization_implementation_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, step_key text NOT NULL, title text NOT NULL, owner text NOT NULL DEFAULT 'sarah', status text NOT NULL DEFAULT 'pendente' CHECK(status IN('pendente','em_andamento','bloqueado','concluido')), due_on date, notes text, evidence_url text, completed_at timestamptz, completed_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,step_key));
ALTER TABLE public.organization_implementation_steps ENABLE ROW LEVEL SECURITY;
CREATE POLICY implementation_steps_access ON public.organization_implementation_steps FOR ALL TO authenticated USING (public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=organization_implementation_steps.organization_id AND m.user_id=auth.uid() AND m.papel::text IN('admin','manager','sindico'))) WITH CHECK (public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=organization_implementation_steps.organization_id AND m.user_id=auth.uid() AND m.papel::text IN('admin','manager','sindico')));
CREATE OR REPLACE FUNCTION public.seed_organization_implementation(p_organization_id uuid) RETURNS SETOF public.organization_implementation_steps LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT(public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=p_organization_id AND m.user_id=auth.uid() AND m.papel::text IN('admin','manager'))) THEN RAISE EXCEPTION 'Sem permissão'; END IF; INSERT INTO public.organization_implementation_steps(organization_id,step_key,title,owner) VALUES (p_organization_id,'infra','Infraestrutura e equipamentos','sarah'),(p_organization_id,'grade','Grade de aulas','sarah'),(p_organization_id,'equipe','Equipe e professor responsável','rony'),(p_organization_id,'acesso','QR, acessos e onboarding','sarah'),(p_organization_id,'health_day','Health Day de ativação','rony'),(p_organization_id,'comunicacao','Comunicado e captação','sarah') ON CONFLICT(organization_id,step_key) DO NOTHING; RETURN QUERY SELECT * FROM public.organization_implementation_steps WHERE organization_id=p_organization_id ORDER BY created_at; END $$;
REVOKE ALL ON FUNCTION public.seed_organization_implementation(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.seed_organization_implementation(uuid) TO authenticated;
